sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader backdrop;
uniform float amount;
half4 main(float2 coord) {
    half4 s = image.eval(coord);
    if (s.a <= 0.0) return s;
    half4 b = backdrop.eval(coord);
    float3 under = b.a > 0.0 ? float3(b.rgb) / float(b.a) : float3(0.0);
    float3 own = float3(s.rgb) / float(s.a);
    float3 rgb = mix(own, abs(own - under), clamp(amount, 0.0, 1.0));
    return half4(half3(rgb) * s.a, s.a);
}
